create type public.proficiency_level as enum ('beginner', 'intermediate', 'advanced', 'expert');
create type public.talent_visibility as enum ('private', 'organization', 'recruiters');

create table public.skills (id uuid primary key default gen_random_uuid(), name text not null check (char_length(trim(name)) between 1 and 80), category text check (category is null or char_length(trim(category)) <= 80), created_at timestamptz not null default now());
create unique index skills_name_case_insensitive_idx on public.skills (lower(name));
create table public.employee_skills (id uuid primary key default gen_random_uuid(), employee_id uuid not null references public.employees(id) on delete cascade, skill_id uuid not null references public.skills(id) on delete restrict, proficiency public.proficiency_level not null default 'beginner', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(employee_id, skill_id));
create table public.experiences (id uuid primary key default gen_random_uuid(), employee_id uuid not null references public.employees(id) on delete cascade, company text not null check(char_length(trim(company)) between 1 and 120), job_title text not null check(char_length(trim(job_title)) between 1 and 120), employment_type text check(employment_type is null or char_length(employment_type)<=40), start_date date not null, end_date date, is_current boolean not null default false, description text check(description is null or char_length(description)<=2000), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check((is_current and end_date is null) or (not is_current and end_date is not null)), check(end_date is null or start_date <= end_date));
create table public.education (id uuid primary key default gen_random_uuid(), employee_id uuid not null references public.employees(id) on delete cascade, institution text not null check(char_length(trim(institution)) between 1 and 160), qualification text not null check(char_length(trim(qualification)) between 1 and 120), field_of_study text check(field_of_study is null or char_length(field_of_study)<=120), start_date date, end_date date, description text check(description is null or char_length(description)<=1000), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(start_date is null or end_date is null or start_date <= end_date));
create table public.certifications (id uuid primary key default gen_random_uuid(), employee_id uuid not null references public.employees(id) on delete cascade, name text not null check(char_length(trim(name)) between 1 and 140), issuer text not null check(char_length(trim(issuer)) between 1 and 140), issue_date date, expiry_date date, credential_id text check(credential_id is null or char_length(credential_id)<=120), verification_url text check(verification_url is null or verification_url ~ '^https://'), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(issue_date is null or expiry_date is null or issue_date <= expiry_date));
create table public.projects (id uuid primary key default gen_random_uuid(), employee_id uuid not null references public.employees(id) on delete cascade, name text not null check(char_length(trim(name)) between 1 and 140), role text check(role is null or char_length(role)<=120), description text check(description is null or char_length(description)<=2000), technologies text[] not null default '{}', start_date date, end_date date, is_current boolean not null default false, project_url text check(project_url is null or project_url ~ '^https://'), visibility public.talent_visibility not null default 'private', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check((is_current and end_date is null) or (not is_current and end_date is not null)), check(start_date is null or end_date is null or start_date <= end_date));
create table public.achievements (id uuid primary key default gen_random_uuid(), employee_id uuid not null references public.employees(id) on delete cascade, title text not null check(char_length(trim(title)) between 1 and 140), description text check(description is null or char_length(description)<=1500), achieved_on date, issuer text check(issuer is null or char_length(issuer)<=140), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create sequence public.talent_id_sequence;
create table public.talent_profiles (employee_id uuid primary key references public.employees(id) on delete cascade, talent_id text not null unique default ('TAL-' || lpad(nextval('public.talent_id_sequence')::text, 6, '0')), professional_name text check(professional_name is null or char_length(trim(professional_name)) between 1 and 100), professional_title text check(professional_title is null or char_length(trim(professional_title))<=120), summary text check(summary is null or char_length(summary)<=1500), visibility public.talent_visibility not null default 'private', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(talent_id ~ '^TAL-[0-9]{6,}$'));
create table public.talent_profile_visibility (id uuid primary key default gen_random_uuid(), talent_profile_employee_id uuid not null references public.talent_profiles(employee_id) on delete cascade, viewer_profile_id uuid references public.profiles(id) on delete cascade, visibility public.talent_visibility not null, created_at timestamptz not null default now(), unique(talent_profile_employee_id, viewer_profile_id));
create table public.resumes (id uuid primary key default gen_random_uuid(), employee_id uuid not null unique references public.employees(id) on delete cascade, storage_path text not null unique check(storage_path ~ '^resumes/[0-9a-f-]+/[^/]+\.pdf$'), file_name text not null check(char_length(file_name) between 1 and 180), size_bytes integer not null check(size_bytes > 0 and size_bytes <= 5242880), mime_type text not null check(mime_type = 'application/pdf'), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index professional_employee_idx on public.employee_skills(employee_id); create index experiences_employee_idx on public.experiences(employee_id); create index education_employee_idx on public.education(employee_id); create index certifications_employee_idx on public.certifications(employee_id); create index projects_employee_idx on public.projects(employee_id); create index achievements_employee_idx on public.achievements(employee_id);
create function public.owns_professional_employee(target uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.employees where id=target and profile_id=auth.uid()) $$;
grant execute on function public.owns_professional_employee(uuid) to authenticated;
alter table public.skills enable row level security; alter table public.employee_skills enable row level security; alter table public.experiences enable row level security; alter table public.education enable row level security; alter table public.certifications enable row level security; alter table public.projects enable row level security; alter table public.achievements enable row level security; alter table public.talent_profiles enable row level security; alter table public.talent_profile_visibility enable row level security; alter table public.resumes enable row level security;
create policy skills_own_read on public.skills for select to authenticated using(exists(select 1 from public.employee_skills es where es.skill_id=skills.id and public.owns_professional_employee(es.employee_id)) or public.is_hr_or_admin());
create policy skills_hr_manage on public.skills for all to authenticated using(public.is_hr_or_admin()) with check(public.is_hr_or_admin());
create policy professional_self on public.employee_skills for all to authenticated using(public.owns_professional_employee(employee_id)) with check(public.owns_professional_employee(employee_id));
create policy professional_hr_skills on public.employee_skills for all to authenticated using(public.is_hr_or_admin()) with check(public.is_hr_or_admin());
create policy professional_self_experience on public.experiences for all to authenticated using(public.owns_professional_employee(employee_id)) with check(public.owns_professional_employee(employee_id));
create policy professional_self_education on public.education for all to authenticated using(public.owns_professional_employee(employee_id)) with check(public.owns_professional_employee(employee_id));
create policy professional_self_certifications on public.certifications for all to authenticated using(public.owns_professional_employee(employee_id)) with check(public.owns_professional_employee(employee_id));
create policy professional_self_projects on public.projects for all to authenticated using(public.owns_professional_employee(employee_id)) with check(public.owns_professional_employee(employee_id));
create policy professional_self_achievements on public.achievements for all to authenticated using(public.owns_professional_employee(employee_id)) with check(public.owns_professional_employee(employee_id));
create policy talent_self on public.talent_profiles for all to authenticated using(public.owns_professional_employee(employee_id)) with check(public.owns_professional_employee(employee_id));
create policy visibility_self on public.talent_profile_visibility for all to authenticated using(public.owns_professional_employee(talent_profile_employee_id)) with check(public.owns_professional_employee(talent_profile_employee_id));
create policy resumes_self on public.resumes for all to authenticated using(public.owns_professional_employee(employee_id)) with check(public.owns_professional_employee(employee_id));
create trigger employee_skills_updated before update on public.employee_skills for each row execute function public.set_updated_at(); create trigger experiences_updated before update on public.experiences for each row execute function public.set_updated_at(); create trigger education_updated before update on public.education for each row execute function public.set_updated_at(); create trigger certifications_updated before update on public.certifications for each row execute function public.set_updated_at(); create trigger projects_updated before update on public.projects for each row execute function public.set_updated_at(); create trigger achievements_updated before update on public.achievements for each row execute function public.set_updated_at(); create trigger talent_profiles_updated before update on public.talent_profiles for each row execute function public.set_updated_at(); create trigger resumes_updated before update on public.resumes for each row execute function public.set_updated_at();
